{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://codex-desk-meter.local/schema/end-to-end-result.schema.json",
  "title": "Codex Desk Meter end-to-end experiment result",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "result_id",
    "run_id",
    "manifest_id",
    "baseline_id",
    "experiment_id",
    "manifest",
    "baseline",
    "feature_results",
    "core_results",
    "integration_results",
    "gui_scores",
    "provider_matrix",
    "build",
    "host",
    "transport",
    "hardware",
    "telemetry",
    "product_pass"
  ],
  "properties": {
    "schema_version": {
      "const": 1
    },
    "result_id": {
      "$ref": "#/$defs/identifier"
    },
    "run_id": {
      "$ref": "#/$defs/identifier"
    },
    "manifest_id": {
      "$ref": "#/$defs/identifier"
    },
    "baseline_id": {
      "$ref": "#/$defs/identifier"
    },
    "experiment_id": {
      "const": "version-2-end-to-end-v1"
    },
    "manifest": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "experiment_id",
        "baseline_id",
        "path"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/identifier"
        },
        "experiment_id": {
          "const": "version-2-end-to-end-v1"
        },
        "baseline_id": {
          "$ref": "#/$defs/identifier"
        },
        "path": {
          "$ref": "#/$defs/path"
        }
      }
    },
    "baseline": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "experiment_id",
        "commit",
        "ref"
      ],
      "properties": {
        "id": {
          "$ref": "#/$defs/identifier"
        },
        "experiment_id": {
          "const": "version-2-end-to-end-v1"
        },
        "commit": {
          "type": "string",
          "pattern": "^[A-Fa-f0-9]{7,64}$"
        },
        "ref": {
          "$ref": "#/$defs/identifier"
        }
      }
    },
    "feature_results": {
      "$ref": "#/$defs/featureResults"
    },
    "core_results": {
      "$ref": "#/$defs/coreResults"
    },
    "integration_results": {
      "$ref": "#/$defs/integrationResults"
    },
    "gui_scores": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "G1",
        "G2",
        "G3",
        "G4",
        "G5",
        "G6"
      ],
      "properties": {
        "G1": {
          "$ref": "#/$defs/guiScore"
        },
        "G2": {
          "$ref": "#/$defs/guiScore"
        },
        "G3": {
          "$ref": "#/$defs/guiScore"
        },
        "G4": {
          "$ref": "#/$defs/guiScore"
        },
        "G5": {
          "$ref": "#/$defs/guiScore"
        },
        "G6": {
          "$ref": "#/$defs/guiScore"
        }
      }
    },
    "provider_matrix": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/providerResult"
      }
    },
    "build": {
      "unevaluatedProperties": false,
      "allOf": [
        {
          "$ref": "#/$defs/validationBlock"
        },
        {
          "type": "object",
          "required": [
            "target"
          ],
          "properties": {
            "target": {
              "type": "string",
              "minLength": 1
            }
          }
        }
      ]
    },
    "host": {
      "unevaluatedProperties": false,
      "allOf": [
        {
          "$ref": "#/$defs/validationBlock"
        },
        {
          "type": "object",
          "required": [
            "host_id"
          ],
          "properties": {
            "host_id": {
              "$ref": "#/$defs/identity"
            }
          }
        }
      ]
    },
    "transport": {
      "unevaluatedProperties": false,
      "allOf": [
        {
          "$ref": "#/$defs/validationBlock"
        },
        {
          "type": "object",
          "required": [
            "choice"
          ],
          "properties": {
            "choice": {
              "enum": [
                "usb-serial",
                "local-wifi",
                null
              ]
            }
          }
        }
      ]
    },
    "hardware": {
      "unevaluatedProperties": false,
      "allOf": [
        {
          "$ref": "#/$defs/validationBlock"
        },
        {
          "type": "object",
          "required": [
            "board"
          ],
          "properties": {
            "board": {
              "const": "waveshare-esp32-s3-lcd-3.16"
            }
          }
        }
      ]
    },
    "telemetry": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "wall_clock_seconds",
        "agent_tokens",
        "token_total_definition",
        "provider_total_definition",
        "availability_reason",
        "evidence"
      ],
      "properties": {
        "wall_clock_seconds": {
          "type": [
            "number",
            "null"
          ],
          "minimum": 0
        },
        "agent_tokens": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "input",
            "output",
            "cached",
            "reasoning",
            "provider_total",
            "total"
          ],
          "properties": {
            "input": {
              "$ref": "#/$defs/nonnegativeIntegerOrNull"
            },
            "output": {
              "$ref": "#/$defs/nonnegativeIntegerOrNull"
            },
            "cached": {
              "$ref": "#/$defs/nonnegativeIntegerOrNull"
            },
            "reasoning": {
              "$ref": "#/$defs/nonnegativeIntegerOrNull"
            },
            "provider_total": {
              "$ref": "#/$defs/nonnegativeIntegerOrNull"
            },
            "total": {
              "$ref": "#/$defs/nonnegativeIntegerOrNull"
            }
          }
        },
        "availability_reason": {
          "type": "string",
          "minLength": 1
        },
        "token_total_definition": {
          "const": "input_plus_output_excludes_cached_and_reasoning"
        },
        "provider_total_definition": {
          "const": "provider_reported_total_preserved_without_recomputation"
        },
        "evidence": {
          "$ref": "#/$defs/evidence"
        }
      }
    },
    "product_pass": {
      "type": "boolean"
    }
  },
  "$defs": {
    "identifier": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]*$"
    },
    "identity": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[a-z0-9][a-z0-9._-]*$"
    },
    "identityOrNull": {
      "type": [
        "string",
        "null"
      ],
      "minLength": 1,
      "pattern": "^[a-z0-9][a-z0-9._-]*$"
    },
    "path": {
      "type": "string",
      "minLength": 1,
      "pattern": "^(?!/)(?![A-Za-z]:)[^\\\\]+$"
    },
    "evidence": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/path"
      }
    },
    "status": {
      "enum": [
        "pass",
        "partial",
        "fail",
        "not_run",
        "blocked",
        "timeout"
      ]
    },
    "resultEntry": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "status",
        "scope",
        "evidence",
        "reason"
      ],
      "properties": {
        "status": {
          "$ref": "#/$defs/status"
        },
        "scope": {
          "type": "string",
          "minLength": 1
        },
        "evidence": {
          "$ref": "#/$defs/evidence"
        },
        "reason": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        }
      }
